arguments.prompt:
You are working in /tmp/sv-22f9c1a9702548749323732db63ec675/ShipmentTracker - a Blazor Web App with Interactive Auto Global mode and Individual authentication scaffolded. The solution has two projects:
- ShipmentTracker (server) 
- ShipmentTracker.Client (WebAssembly client)

The server has EF Core with SQLite, ASP.NET Core Identity already set up. The client project has auth state deserialization already configured.

## Task

Implement a shipment tracking application for a logistics company. Do the following steps IN ORDER:

### 1. Create shared models in the Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

public class ShipmentSummary
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
}

public class ShipmentDetail : ShipmentSummary
{
    public DateTime ShippedDate { get; set; }
    public string CarrierName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public List<TrackingEvent> Events { get; set; } = new();
}

public class TrackingEvent
{
    public DateTime Timestamp { get; set; }
    public string Location { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
}
```

### 2. Create the service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentSummary>> GetShipmentsAsync(ShipmentStatus? statusFilter = null);
    Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDetail?> GetShipmentByIdAsync(int id);
    Task UpdateStatusAsync(int id, ShipmentStatus newStatus, string location, string description);
}
```

### 3. Create the client-side HttpClient implementation

Create `ShipmentTracker.Client/Services/ShipmentServiceClient.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var url = statusFilter.HasValue
            ? $"/api/shipments?status={statusFilter.Value}"
            : "/api/shipments";
        return await http.GetFromJsonAsync<List<ShipmentSummary>>(url) ?? new();
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<ShipmentDetail?>($"/api/shipments/track/{trackingNumber}");
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await http.GetFromJsonAsync<ShipmentDetail?>($"/api/shipments/{id}");
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus, string location, string description)
    {
        var payload = new { Status = newStatus, Location = location, Description = description };
        await http.PostAsJsonAsync($"/api/shipments/{id}/status", payload);
    }
}
```

### 4. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to add:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, ShipmentServiceClient>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

Wait - WebAssembly doesn't have `AddHttpClient`. Use `AddScoped` with `HttpClient` instead:

```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentServiceClient>();

await builder.Build().RunAsync();
```

### 5. Create the server-side Shipment entity and update DbContext

Create `ShipmentTracker/Data/ShipmentEntity.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class ShipmentEntity
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; } // maps to ShipmentStatus enum

    public DateTime EstimatedDelivery { get; set; }
    public DateTime ShippedDate { get; set; }

    [MaxLength(100)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(100)]
    public string CarrierName { get; set; } = string.Empty;

    public double WeightKg { get; set; }

    public List<TrackingEventEntity> Events { get; set; } = new();
}

public class TrackingEventEntity
{
    public int Id { get; set; }
    public int ShipmentEntityId { get; set; }
    public DateTime Timestamp { get; set; }

    [MaxLength(200)]
    public string Location { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;

    public int Status { get; set; }
}
```

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add DbSets:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();
    public DbSet<TrackingEventEntity> TrackingEvents => Set<TrackingEventEntity>();
}
```

### 6. Create and apply migration

Run:
```bash
cd /tmp/sv-22f9c1a9702548749323732db63ec675/ShipmentTracker/ShipmentTracker
dotnet ef migrations add AddShipments --output-dir Data/Migrations
dotnet ef database update
```

If `dotnet ef` is not available, install it first:
```bash
dotnet tool install --global dotnet-ef
```

### 7. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServiceServer.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();
        if (statusFilter.HasValue)
            query = query.Where(s => s.Status == (int)statusFilter.Value);

        return await query.Select(s => new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentStatus)s.Status,
            EstimatedDelivery = s.EstimatedDelivery,
            RecipientName = s.RecipientName
        }).ToListAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments
            .Include(s => s.Events)
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        return entity is null ? null : MapToDetail(entity);
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        var entity = await db.Shipments
            .Include(s => s.Events)
            .FirstOrDefaultAsync(s => s.Id == id);

        return entity is null ? null : MapToDetail(entity);
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus, string location, string description)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is null) return;

        entity.Status = (int)newStatus;
        db.TrackingEvents.Add(new TrackingEventEntity
        {
            ShipmentEntityId = id,
            Timestamp = DateTime.UtcNow,
            Location = location,
            Description = description,
            Status = (int)newStatus
        });

        await db.SaveChangesAsync();
    }

    private static ShipmentDetail MapToDetail(ShipmentEntity entity) => new()
    {
        Id = entity.Id,
        TrackingNumber = entity.TrackingNumber,
        Origin = entity.Origin,
        Destination = entity.Destination,
        Status = (ShipmentStatus)entity.Status,
        EstimatedDelivery = entity.EstimatedDelivery,
        RecipientName = entity.RecipientName,
        ShippedDate = entity.ShippedDate,
        CarrierName = entity.CarrierName,
        WeightKg = entity.WeightKg,
        Events = entity.Events
            .OrderByDescending(e => e.Timestamp)
            .Select(e => new TrackingEvent
            {
                Timestamp = e.Timestamp,
                Location = e.Location,
                Description = e.Description,
                Status = (ShipmentStatus)e.Status
            }).ToList()
    };
}
