using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();
        if (statusFilter.HasValue)
            query = query.Where(s => s.Status == (int)statusFilter.Value);

        return await query.Select(s => new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentStatus)s.Status,
            EstimatedDelivery = s.EstimatedDelivery,
            RecipientName = s.RecipientName
        }).ToListAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments
            .Include(s => s.Events)
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        return entity is null ? null : MapToDetail(entity);
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        var entity = await db.Shipments
            .Include(s => s.Events)
            .FirstOrDefaultAsync(s => s.Id == id);

        return entity is null ? null : MapToDetail(entity);
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus, string location, string description)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is null) return;

        entity.Status = (int)newStatus;
        db.TrackingEvents.Add(new TrackingEventEntity
        {
            ShipmentEntityId = id,
            Timestamp = DateTime.UtcNow,
            Location = location,
            Description = description,
            Status = (int)newStatus
        });

        await db.SaveChangesAsync();
    }

    private static ShipmentDetail MapToDetail(ShipmentEntity entity) => new()
    {
        Id = entity.Id,
        TrackingNumber = entity.TrackingNumber,
        Origin = entity.Origin,
        Destination = entity.Destination,
        Status = (ShipmentStatus)entity.Status,
        EstimatedDelivery = entity.EstimatedDelivery,
        RecipientName = entity.RecipientName,
        ShippedDate = entity.ShippedDate,
        CarrierName = entity.CarrierName,
        WeightKg = entity.WeightKg,
        Events = entity.Events
            .OrderByDescending(e => e.Timestamp)
            .Select(e => new TrackingEvent
            {
                Timestamp = e.Timestamp,
                Location = e.Location,
                Description = e.Description,
                Status = (ShipmentStatus)e.Status
            }).ToList()
    };
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        group.MapGet("/", async (ShipmentStatus? status, IShipmentService service) =>
        {
            return Results.Ok(await service.GetShipmentsAsync(status));
        }).RequireAuthorization();

        group.MapGet("/{id:int}", async (int id, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByIdAsync(id);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).RequireAuthorization();

        group.MapPost("/{id:int}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, request.Status, request.Location, request.Description);
            return Results.Ok();
        }).RequireAuthorization();
    }
}

public record StatusUpdateRequest(ShipmentStatus Status, string Location, string Description);

