@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<div class="container mt-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Enter your tracking number to check shipment status.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. TRK-20260701-001"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning">@errorMessage</div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>@shipment.TrackingNumber</strong>
                <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row mb-3">
                    <div class="col-md-4"><strong>From:</strong> @shipment.Origin</div>
                    <div class="col-md-4"><strong>To:</strong> @shipment.Destination</div>
                    <div class="col-md-4"><strong>Recipient:</strong> @shipment.RecipientName</div>
                </div>
                <div class="row mb-3">
                    <div class="col-md-4"><strong>Carrier:</strong> @shipment.CarrierName</div>
                    <div class="col-md-4"><strong>Weight:</strong> @shipment.WeightKg kg</div>
                    <div class="col-md-4"><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</div>
                </div>

                @if (shipment.Events.Any())
                {
                    <h5 class="mt-3">Tracking History</h5>
                    <table class="table table-sm">
                        <thead>
                            <tr><th>Date</th><th>Location</th><th>Status</th><th>Details</th></tr>
                        </thead>
                        <tbody>
                            @foreach (var evt in shipment.Events)
                            {
                                <tr>
                                    <td>@evt.Timestamp.ToString("MMM dd, HH:mm")</td>
                                    <td>@evt.Location</td>
                                    <td><span class="badge @GetStatusBadgeClass(evt.Status)">@evt.Status</span></td>
                                    <td>@evt.Description</td>
                                </tr>
                            }
                        </tbody>
                    </table>
                }
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDetail? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (shipment is null)
                errorMessage = "No shipment found with that tracking number.";
        }
        catch
        {
            errorMessage = "Unable to retrieve shipment information. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

