@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Shipment Details</PageTitle>

<div class="container mt-4">
    @if (isLoading)
    {
        <div class="d-flex justify-content-center my-4">
            <div class="spinner-border" role="status"></div>
        </div>
    }
    else if (shipment is null)
    {
        <div class="alert alert-warning">Shipment not found.</div>
        <a href="/shipments" class="btn btn-secondary">Back to Dashboard</a>
    }
    else
    {
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h1>Shipment @shipment.TrackingNumber</h1>
            <a href="/shipments" class="btn btn-outline-secondary">Back</a>
        </div>

        <div class="row mb-4">
            <div class="col-md-6">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Shipment Info</h5>
                        <dl class="row mb-0">
                            <dt class="col-sm-5">Status</dt>
                            <dd class="col-sm-7"><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                            <dt class="col-sm-5">Origin</dt>
                            <dd class="col-sm-7">@shipment.Origin</dd>
                            <dt class="col-sm-5">Destination</dt>
                            <dd class="col-sm-7">@shipment.Destination</dd>
                            <dt class="col-sm-5">Recipient</dt>
                            <dd class="col-sm-7">@shipment.RecipientName</dd>
                            <dt class="col-sm-5">Carrier</dt>
                            <dd class="col-sm-7">@shipment.CarrierName</dd>
                            <dt class="col-sm-5">Weight</dt>
                            <dd class="col-sm-7">@shipment.WeightKg kg</dd>
                            <dt class="col-sm-5">Shipped</dt>
                            <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                            <dt class="col-sm-5">Est. Delivery</dt>
                            <dd class="col-sm-7">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                        </dl>
                    </div>
                </div>
            </div>
            <div class="col-md-6">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Update Status</h5>
                        <div class="mb-2">
                            <label class="form-label">New Status</label>
                            <select class="form-select" @bind="newStatus">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Location</label>
                            <input type="text" class="form-control" @bind="updateLocation" placeholder="Current location" />
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <input type="text" class="form-control" @bind="updateDescription" placeholder="Status description" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdateStatus" disabled="@isUpdating">
                            @if (isUpdating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Status
                        </button>
                        @if (updateSuccess)
                        {
                            <span class="text-success ms-2">✓ Updated</span>
                        }
                    </div>
                </div>
            </div>
        </div>

        @if (shipment.Events.Any())
        {
            <h4>Tracking History</h4>
            <table class="table">
                <thead>
                    <tr><th>Date</th><th>Location</th><th>Status</th><th>Details</th></tr>
                </thead>
                <tbody>
                    @foreach (var evt in shipment.Events)
                    {
                        <tr>
                            <td>@evt.Timestamp.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>@evt.Location</td>
                            <td><span class="badge @GetStatusBadgeClass(evt.Status)">@evt.Status</span></td>
                            <td>@evt.Description</td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private ShipmentDetail? shipment;
    private bool isLoading = true;
    private bool isUpdating;
    private bool updateSuccess;
    private ShipmentStatus newStatus;
    private string updateLocation = string.Empty;
    private string updateDescription = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipment();
    }

    private async Task LoadShipment()
    {
        isLoading = true;
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is not null)
            newStatus = shipment.Status;
        isLoading = false;
    }

    private async Task UpdateStatus()
    {
        if (string.IsNullOrWhiteSpace(updateLocation) || string.IsNullOrWhiteSpace(updateDescription))
            return;

        isUpdating = true;
        updateSuccess = false;
        await ShipmentService.UpdateStatusAsync(Id, newStatus, updateLocation, updateDescription);
        await LoadShipment();
        updateSuccess = true;
        isUpdating = false;
        updateLocation = string.Empty;
        updateDescription = string.Empty;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

