                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Search</label>
            <input type="text" class="form-control" placeholder="Search tracking # or destination..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
    </div>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center my-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (filteredShipments.Any())
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in filteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Destination</td>
                            <td>@s.RecipientName</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                <a href="/shipments/@s.Id" class="btn btn-sm btn-outline-primary">Details</a>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @filteredShipments.Count of @shipments.Count shipments</p>
    }
    else
    {
        <div class="alert alert-info">No shipments found.</div>
    }
</div>

@code {
    private List<ShipmentSummary> shipments = new();
    private ShipmentStatus? statusFilter;
    private string searchTerm = string.Empty;
    private bool isLoading = true;

    private List<ShipmentSummary> filteredShipments => shipments
        .Where(s => string.IsNullOrWhiteSpace(searchTerm)
            || s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        statusFilter = string.IsNullOrEmpty(e.Value?.ToString())
            ? null
            : (ShipmentStatus)int.Parse(e.Value.ToString()!);
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetShipmentsAsync(statusFilter);
        }
        catch
        {
            shipments = new();
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

