@code {
    [Parameter] public int Id { get; set; }

    private ShipmentDetail? shipment;
    private bool isLoading = true;
    private bool isUpdating;
    private bool updateSuccess;
    private ShipmentStatus newStatus;
    private string updateLocation = string.Empty;
    private string updateDescription = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipment();
    }

    private async Task LoadShipment()
    {
        isLoading = true;
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is not null)
            newStatus = shipment.Status;
        isLoading = false;
    }

    private async Task UpdateStatus()
    {
        if (string.IsNullOrWhiteSpace(updateLocation) || string.IsNullOrWhiteSpace(updateDescription))
            return;

        isUpdating = true;
        updateSuccess = false;
        await ShipmentService.UpdateStatusAsync(Id, newStatus, updateLocation, updateDescription);
        await LoadShipment();
        updateSuccess = true;
        isUpdating = false;
        updateLocation = string.Empty;
        updateDescription = string.Empty;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

